INSERT INTO `about_page_content` VALUES (1,'hero','{\"title\":\"Về chúng tôi\",\"subtitle\":\"Hệ thống Y tế chất lượng cao - Chăm sóc sức khỏe toàn diện\",\"backgroundImage\":\"http://localhost:8080/api/images/articles/01d4a7ba-db4b-4758-9688-b4781445cff3.webp\"}',1,'2026-02-04 20:13:08','2026-02-05 02:29:04'),(2,'mission','{\"label\":\"SỨ MỆNH CỦA CHÚNG TÔI\",\"title\":\"Mang đến dịch vụ y tế chất lượng cao\",\"description\":\"MEDLATEC được thành lập với sứ mệnh cung cấp dịch vụ chăm sóc sức khỏe toàn diện, chất lượng cao với chi phí hợp lý cho mọi người dân Việt Nam. Chúng tôi tin rằng mỗi người đều xứng đáng được tiếp cận với các dịch vụ y tế hiện đại, an toàn và hiệu quả.\",\"features\":[\"Đội ngũ bác sĩ chuyên môn cao\",\"Trang thiết bị hiện đại\",\"Quy trình khám chữa bệnh chuẩn quốc tế\"],\"imageUrl\":\"http://localhost:8080/api/images/articles/8811bf21-b141-47c9-97d0-5b32f97c4305.png\"}',1,'2026-02-04 20:13:08','2026-02-05 02:28:48'),(3,'values','[{\"title\":\"Tận tâm\",\"description\":\"Chúng tôi đặt sức khỏe và hạnh phúc của bệnh nhân lên hàng đầu trong mọi quyết định\",\"icon\":\"HeartOutlined\",\"color\":\"#ff4d4f\"},{\"title\":\"An toàn\",\"description\":\"Cam kết cung cấp dịch vụ y tế an toàn với các tiêu chuẩn quốc tế\",\"icon\":\"SafetyOutlined\",\"color\":\"#52c41a\"},{\"title\":\"Chuyên nghiệp\",\"description\":\"Đội ngũ bác sĩ giàu kinh nghiệm, được đào tạo bài bản\",\"icon\":\"TeamOutlined\",\"color\":\"#1890ff\"},{\"title\":\"Chất lượng\",\"description\":\"Không ngừng nâng cao chất lượng dịch vụ và cơ sở vật chất\",\"icon\":\"TrophyOutlined\",\"color\":\"#faad14\"}]',1,'2026-02-04 20:13:08','2026-02-04 14:06:57'),(4,'achievements','[{\"_section\":true,\"sectionTitle\":\"Con số ấn tượng\",\"backgroundImage\":\"http://localhost:8080/api/images/articles/3af35edf-996a-4916-a378-4cdcd7c14f90.webp\",\"labelColor\":\"#ffffff\",\"titleColor\":\"#ffffff\",\"textColor\":\"#ffffff\",\"overlayColor\":\"rgba(0, 0, 0, 0.7)\"},{\"title\":\"Bệnh nhân\",\"value\