INSERT INTO `certifications` VALUES (1,'ISO 15189:2022','????','#1890ff',' ISO 15189:2022 (tương đương Tiêu chuẩn quốc gia TCVN 15189:2014) là tiêu chuẩn quy định các yêu cầu về năng lực và chất lượng đối với các phòng xét nghiệm y tế. Tiêu chuẩn này được xây dựng dựa trên các yêu cầu của tiêu chuẩn ISO/IEC 17025 và ISO 9001, ngoài ra bổ sung thêm các yêu cầu riêng về đảm bảo chất lượng trong lĩnh vực thử nghiệm y tế. ',1,1,'2026-02-03 02:27:44','2026-02-03 18:45:53','http://localhost:8080/api/images/articles/b88af11a-9865-4a5d-aad2-41847414a818.png'),(2,'CAP ACCREDITED','???','#52c41a',' CAP là tên viết tắt của Hiệp hội Bệnh học Hoa Kỳ (College of American Pathologists), đây là cơ quan công nhận						chất lượng được ưu tiên lựa chọn bởi hơn 8.000 phòng thí nghiệm ở hơn 50 quốc gia trên thế giới. Cơ quan này cung cấp các tiêu chuẩn nghiêm ngặt về chất lượng xét nghiệm, cung cấp cơ hội học hỏi, phát triển toàn diện để phòng xét nghiệm có thể hỗ trợ tốt nhất các bác sĩ trong khâu đưa ra chẩn đoán điều trị chính xác cho bệnh nhân thông qua kết quả xét nghiệm. ',1,2,'2026-02-03 02:27:44','2026-02-03 18:47:44','http://localhost:8080/api/images/articles/1d502540-ffed-4543-ae2e-dfac9a8bc9b6.png'),(3,'B??? Y T???','???????','#fa8c16','C├┤ng nhß║¡n tß╗½ Bß╗Ö Y tß║┐ Viß╗çt Nam',1,3,'2026-02-03 02:27:44','2026-02-03 02:27:44',NULL),(4,'TOP 10 VN','????','#722ed1','Xß║┐p hß║íng trong top 10 bß╗çnh viß╗çn tß╗æt nhß║Ñt Viß╗çt Nam',1,4,'2026-02-03 02:27:44','2026-02-03 02:27:44',NULL),(5,'JCI STANDARD','????','#eb2f96','Ti├¬u chuß║®n quß╗æc tß║┐ vß╗ü chß║Ñt lã░ß╗úng bß╗çnh viß╗çn',1,5,'2026-02-03 02:27:44','2026-02-03 02:27:44',NULL),(6,'NABL CERTIFIED','????','#13c2c2','Chß╗®ng nhß║¡n tß╗½ tß╗ò chß╗®c NABL vß╗ü n─âng lß╗▒c thß╗¡ nghiß╗çm',1,6,'2026-02-03 02:27:44','2026-02-03 02:27:44',NULL);
