INSERT INTO `medical_services` VALUES (1,1,'Khám Nội truyền nhiễm','kham-noi-truyen-nhiem','Chỉ áp dụng cho khách hàng thanh toán thành công trong thời gian ưu đãi.\nBảo lưu thời gian sử dụng deal trong 3 tháng tính từ ngày mua.\nMỗi khách hàng chỉ được mua 01 deal.\nKhông hoàn tiền nếu khách hàng đã mua deal nhưng không sử dụng dịch vụ trong thời gian quy định.\nKhông áp dụng đồng thời với chương trình ưu đãi khác.\nChỉ áp dụng với khách hàng có quốc tịch Việt Nam.',NULL,'http://localhost:8080/api/images/articles/8403751c-c580-4d68-9094-590c92cbe1bb.webp',1500000.00,1050000.00,30,0,1,1,1,'2026-02-06 12:16:06','2026-02-07 04:43:02','[\"http://localhost:8080/api/images/articles/8403751c-c580-4d68-9094-590c92cbe1bb.webp\",\"http://localhost:8080/api/images/articles/d9d47a8e-fdb3-4630-92c9-b255600fdeb9.webp\",\"http://localhost:8080/api/images/articles/9077e6f8-5ab3-406f-87a5-73352fcb1907.webp\"]'),(4,1,'Gói tầm soát tổn thương thần kinh','goi-tam-soat-ton-thuong-than-kinh','Khám chuyên sâu từ lâm sàng đến cận lâm sàng\nPhát hiện sớm những tổn thương thần kinh\nCông nghệ hiện đại, chẩn đoán chính xác\nĐược bảo lưu 3 tháng sử dụng kể từ ngày đăng ký gói.\nĐăng ký mua tại đây luôn được hưởng ưu đãi tốt hơn.','<h3>Thông tin gói khám</h3><p>Gói tầm soát tổn thương thần kinh được các bác sĩ Bệnh viện Đa khoa Phương Đông xây dựng dành tất cả đối tượng có nguy cơ mắc bệnh để kiểm tra chức năng và phát hiện sớm các bệnh lý liên quan đến não bộ, tủy sống và các dây thần kinh ngoại biên,… Nhằm có phương án điều trị kịp thời, nâng cao cơ hội hồi phục và duy trì sức khỏe lâu dài.</p><h3>Chi tiết gói khám</h3><p>Gói tầm soát tổn thương thần kinh gồm:</p><p><img src=\"https://online.benhvienphuongdong.vn/wp-content/uploads/2025/10/goi-kham-tam-soat-ton-thuong-than-kinh-scaled.png.webp\"></p><h3>Vì sao nên chọn Phương Đông?</h3><ul><li>Đầu tư hệ thống máy móc hiện đại và đồng bộ bao gồm: Máy siêu âm màu 4D, máy chụp X quang, máy chụp MRI 1,5 Tesla, máy chụp CT 128 dãy,… nhập khẩu từ các thương hiệu hàng đầu về sản xuất thiết bị y tế.</li><li>Đội ngũ bác sĩ Phương Đông đều có trình độ chuyên môn cao, kinh nghiệm lâu năm và thái độ chuyên nghiệp, tận tâm phục vụ.</li><li>Không gian bệnh viện khang trang, hiện đại theo mô hình khách sạn 5 sao.</li><li>Khuôn viên xanh mang lại không khí trong lành, thoáng mát.</li><li>Quy trình khám được xây dựng khoa học, an toàn, hạn chế lây nhiễm chéo.</li></ul>','http://localhost:8080/api/images/articles/84b48203-e296-49e5-ba0d-d480f22a4652.webp',7715000.00,3857500.00,50,0,1,1,1,'2026-02-06 12:16:06','2026-02-06 11:29:48','[\"http://localhost:8080/api/images/articles/84b48203-e296-49e5-ba0d-d480f22a4652.webp\"]'),(7,2,'Gói tầm soát đái tháo đường – Đánh giá toàn diện mạch máu và thần kinh','goi-tam-soat-dai-thao-duong-danh-gia-toan-dien-mach-mau-va-than-kinh','- Khám chuyên sâu từ lâm sàng đến cận lâm sàng\n- Phát hiện sớm đái tháo đường – Đánh giá toàn diện mạch máu và thần kinh\n- Công nghệ hiện đại, chẩn đoán chính xác\n- Được bảo lưu 3 tháng sử dụng kể từ ngày đăng ký gói.\n- Đăng ký mua tại đây luôn được hưởng ưu đãi tốt hơn.\n','<h3>Thông tin gói khám</h3><p>Gói tầm soát đái tháo đường – Đánh giá toàn diện mạch máu và thần kinh được các bác sĩ Bệnh viện Đa khoa Phương Đông xây dựng dành tất cả đối tượng có nguy cơ mắc bệnh giúp kiểm tra sức khỏe với các danh mục xét nghiệm và chẩn đoán chuyên sâu. Nhằm có phương án điều trị kịp thời, nâng cao cơ hội hồi phục và duy trì sức khỏe lâu dài.</p><p>Đái tháo đường là một trong những bệnh lý phổ biến gây ảnh hưởng nghiêm trọng đến sức khỏe và chất lượng cuộc sống. Chủ động tầm soát sớm đái tháo đường là chìa khóa giúp bạn bảo vệ sức khỏe và tận hưởng cuộc sống trọn vẹn hơn.</p><h3>Đối tượng thăm khám</h3><p>Đối tượng nên thăm khám gói khám:</p><ul><li>Trên 45 tuổi và mắc huyết áp cao.</li><li>Trên 45 tuổi và bị thừa cân.</li><li>Trên 45 tuổi và có người thân trong gia đình mắc (từng mắc) đái tháo đường.</li><li>Trên 55 tuổi.</li><li>Có hoặc đã có lượng đường trong máu cao trong thai kỳ (tiểu đường thai kỳ).</li><li>Có hội chứng buồng trứng đa nang và thừa cân.</li><li>Người có nhu cầu kiểm tra sức khỏe cơ bản cũng như các vấn đề cơ bản của huyết áp, tim mạch.</li></ul><h3>Vì sao nên chọn Phương Đông?</h3><ul><li>Đầu tư hệ thống máy móc hiện đại và đồng bộ bao gồm: Máy siêu âm màu 4D, máy chụp X quang, máy chụp MRI 1,5 Tesla, máy chụp CT 128 dãy,… nhập khẩu từ các thương hiệu hàng đầu về sản xuất thiết bị y tế.</li><li>Đội ngũ bác sĩ Phương Đông đều có trình độ chuyên môn cao, kinh nghiệm lâu năm và thái độ chuyên nghiệp, tận tâm phục vụ.</li><li>Không gian bệnh viện khang trang, hiện đại theo mô hình khách sạn 5 sao.</li><li>Khuôn viên xanh mang lại không khí trong lành, thoáng mát.</li><li>Quy trình khám được xây dựng khoa học, an toàn, hạn chế lây nhiễm chéo.</li></ul>','http://localhost:8080/api/images/articles/bd64cf22-db18-4086-92fe-8c82541f5fd2.webp',200000.00,200000.00,0,0,1,0,1,'2026-02-06 12:16:06','2026-02-06 11:29:40','[\"http://localhost:8080/api/images/articles/bd64cf22-db18-4086-92fe-8c82541f5fd2.webp\"]');
