INSERT INTO `news_articles` VALUES (14,'Pham Long','<p>aa</p>','2026-02-02 21:25:31.460777',0,'aa','http://localhost:8080/api/images/articles/8c5f62b9-423f-41f7-a4f6-7d06e021f612.jpg',_binary '',_binary '\0','2026-02-02 21:25:31.460777','aa','Chuy??n khoa','aa','2026-02-02 21:46:59.509927','REJECTED',NULL,'medlatec'),(15,'Pham Long','<p>aa</p>','2026-02-02 21:27:05.528176',0,'aa','http://localhost:8080/api/images/articles/340694f1-6e29-4b99-8c35-e0f8917b1bae.jpg',_binary '',_binary '\0','2026-02-02 21:27:05.528176','aaa','S???c kh???e t???ng qu??t','aaa','2026-02-02 21:46:58.984753','REJECTED',NULL,'medlatec'),(16,'Pham Long','<p>aa</p>','2026-02-02 21:29:41.152452',0,'aa','http://localhost:8080/api/images/articles/496177bd-9141-44c5-a644-f50dd640b883.jpg',_binary '',_binary '\0','2026-02-02 21:29:41.152452','aa','Dinh d?????ng','aa','2026-02-02 21:46:57.692907','REJECTED',NULL,'medlatec'),(17,'Pham Long','<p>aa</p>','2026-02-02 21:29:57.876050',0,'â','http://localhost:8080/api/images/articles/028fa574-b326-4248-9a92-e11b75599bf5.jpg',_binary '',_binary '\0','2026-02-02 21:29:57.876050','aaaaaa','Chuy??n khoa','aaa','2026-02-02 21:46:57.173039','REJECTED',NULL,'medlatec'),(18,'Pham Long','<p>aaa</p>','2026-02-03 14:45:43.330475',0,'aa','http://localhost:8080/api/images/articles/9eda6de8-2a33-4c62-80d8-2a101d96d81b.jpg',_binary '',_binary '\0','2026-02-03 14:45:43.330475','aaaaaaa','Sức khỏe tổng quát','aaa','2026-02-03 14:45:43.355805','REJECTED',NULL,'medlatec'),(19,'Pham Long','<p>aaa</p>','2026-02-02 21:31:54.919390',0,'aaaa','http://localhost:8080/api/images/articles/d3cfb3d8-fa6c-4e83-b648-87a72d62d09a.jpg',_binary '',_binary '\0','2026-02-02 21:31:54.919390','aaa','Dinh d?????ng','aaa','2026-02-02 21:46:55.842423','REJECTED',NULL,'medlatec'),(25,'Pham Long','<p><strong>Nữ bệnh nhân 57 tuổi đi khám sức khỏe định kỳ tại MEDLATEC tình cờ phát hiện u dưới niêm mạc dạ dày và nhanh chóng được xử lý triệt để tổn thương ngay trong lần nội soi, tránh được phẫu thuật xâm lấn.</strong>Không triệu chứng đi khám phát hiện u dưới niêm mạc&nbsp;&nbsp;Bệnh nhân N.T.C (57 tuổi, Hà Nội) đến Phòng khám Đa khoa&nbsp;<a href=\"https://medlatec.vn/tin-tuc/medlatec-co-so-2-tai-99-trich-sai-tay-ho-ha-noi-di-vao-hoat-dong-s5-n6735\" rel=\"noopener noreferrer\" target=\"_blank\" style=\"color: rgb(29, 147, 227);\">MEDLATEC Tây Hồ</a>&nbsp;để khám sức khỏe định kỳ. Trước đó, người bệnh hoàn toàn khỏe mạnh, không triệu chứng bất thường. Bác sĩ tiến hành thăm khám lâm sàng và chỉ định các kỹ thuật cận lâm sàng cần thiết.&nbsp;&nbsp;Trong quá trình nội soi dạ dày, bác sĩ phát hiện tại thân vị có một khối lồi kích thước khoảng 1cm, bề mặt niêm mạc bên trên bình thường, khi thăm bằng kìm sinh thiết thấy mật độ chắc, di động, nghĩ đến u dưới niêm mạc. Trước nghi ngờ tổn thương u dưới niêm mạc, các bác sĩ tiếp tục chỉ định siêu âm nội soi (EUS) - phương tiện chẩn đoán chuyên sâu giúp đánh giá chính xác bản chất khối u. Kết quả cho thấy khối u kích thước khoảng 8,2 x 2,2mm, xuất phát từ lớp cơ trơn, ranh giới rõ, cấu trúc giảm âm đồng nhất, không vôi hóa, không chảy máu. Các đặc điểm này gợi ý nhiều đến u cơ trơn lành tính, nhưng vẫn chưa loại trừ GIST, một tổn thương khác nguy cơ cao hơn.&nbsp;&nbsp;<img src=\"https://medlatec.vn/media/68236/file/u-da-day-1.jpg\"><em>Khối u được phát hiện trên hình ảnh siêu âm nội soi&nbsp;</em>Sau khi hội chẩn chuyên khoa Tiêu hóa, bệnh nhân được chỉ định cắt bỏ u qua nội soi dạ dày bằng kỹ thuật ESSD - phương pháp can thiệp hiện đại, ít xâm lấn, giúp loại bỏ hoàn toàn tổn thương mà không cần phẫu thuật mở.&nbsp;<img src=\"https://medlatec.vn/media/68235/file/u-da-day-2.jpg\"><em>Khối u được can thiệp qua nội soi dạ dày bằng kỹ thuật ESSD&nbsp;</em>Quá trình can thiệp được thực hiện bài bản và diễn ra thuận lợi, khối u được lấy trọn vẹn, không ghi nhận biến chứng trong và sau can thiệp. Người bệnh hồi phục nhanh, không đau nhiều, không cần phẫu thuật xâm lấn hay nằm viện kéo dài.&nbsp;Mẫu bệnh phẩm sau cắt được gửi làm giải phẫu bệnh và hoá mô miễn dịch. Kết quả cho chẩn đoán xác định là bệnh nhân mắc u cơ trơn dạ dày lành tính.&nbsp;U cơ trơn - tình trạng lành tính nhưng không nên chủ quan&nbsp;&nbsp;ThS.BSNT Đặng Thị Tâm - Chuyên khoa Nội khoa - Tiêu hóa, Phòng khám Đa khoa MEDLATEC Tây Hồ cho biết, u cơ trơn dạ dày là tổn thương không thường gặp, thường tiến triển âm thầm, ít triệu chứng và bị bỏ sót nếu không nội soi tiêu hoá kiểm tra. Trong thực tế lâm sàng, nếu chỉ nội soi dạ dày đơn thuần thì không chẩn đoán chính xác được bệnh lỳ này, cần kết hợp thêm siêu âm nội soi và có thể phải lấy bệnh phẩm để chẩn đoán.&nbsp;&nbsp;Theo bác sĩ Tâm, trường hợp trên cho thấy vai trò đặc biệt quan trọng của&nbsp;<a href=\"https://medlatec.vn/tin-tuc/tong-hop-cac-loai-ho-so-kham-suc-khoe-dinh-ky-hien-nay-s28-n14518\" rel=\"noopener noreferrer\" target=\"_blank\" style=\"color: rgb(29, 147, 227);\">khám sức khỏe định kỳ</a>&nbsp;và quy trình chẩn đoán - điều trị khép kín. Việc phát hiện sớm, đánh giá chính xác bằng siêu âm nội soi và cắt bỏ u ngay trong quá trình nội soi giúp người bệnh:&nbsp;Loại bỏ triệt để tổn thương; chẩn đoán chính xác bản chất tổn thương;Tránh phẫu thuật mở, giảm đau và thời gian hồi phục;Yên tâm khi có kết quả giải phẫu bệnh xác định lành tính;Giảm chi phí và nguy cơ biến chứng về lâu dài.&nbsp;MEDLATEC - Địa chỉ uy tín chẩn đoán và điều trị toàn diện bệnh lý đường tiêu hóa&nbsp;Không chỉ dừng lại ở phát hiện và xử trí thành công ca bệnh trên, MEDLATEC còn khẳng định thế mạnh nổi bật trong chẩn đoán và điều trị các bệnh lý tiêu hóa nhờ mô hình chăm sóc y tế khép kín, đồng bộ và hiện đại. Tại đây, người bệnh được tiếp cận đầy đủ các kỹ thuật chuyên sâu như nội soi tiêu hóa, siêu âm nội soi, hay các can thiệp điều trị ít xâm lấn cho tới giải phẫu bệnh và tư vấn theo dõi lâu dài, tất cả đều được thực hiện khép kín, nhanh gọn tại MEDLATEC.&nbsp;&nbsp;Đặc biệt, MEDLATEC là một trong số ít đơn vị tại Việt Nam triển khai thường quy siêu âm nội soi (EUS) - kỹ thuật có giá trị cao trong đánh giá các tổn thương dưới niêm mạc đường tiêu hóa. Nhờ đó, bác sĩ có thể xác định chính xác vị trí xuất phát, kích thước, cấu trúc và mức độ xâm lấn của khối u, giúp đưa ra quyết định điều trị phù hợp, hạn chế tối đa can thiệp không cần thiết.&nbsp;&nbsp;<img src=\"https://medlatec.vn/media/65982/file/khoang-cach-giua-2-lan-noi-soi-da-day-2.png\"><em>Trung tâm Tiêu hóa MEDLATEC đầu tư đồng bộ hệ thống trang thiết bị hiện đại hàng đầu trong chẩn đoán - điều trị bệnh lý đường tiêu hóa&nbsp;&nbsp;</em>Bên cạnh đó, việc ứng dụng các kỹ thuật nội soi can thiệp hiện đại như EESD cho phép cắt bỏ triệt để nhiều tổn thương ngay trong quá trình nội soi, thay thế hiệu quả cho phẫu thuật mở truyền thống. Phương pháp này không chỉ giúp người bệnh giảm đau, rút ngắn thời gian hồi phục mà còn hạn chế nguy cơ biến chứng, tiết kiệm chi phí điều trị và nâng cao chất lượng cuộc sống sau can thiệp.&nbsp;&nbsp;Với đội ngũ bác sĩ chuyên khoa Tiêu hóa giàu kinh nghiệm, trang thiết bị hiện đại và quy trình chăm sóc toàn diện, MEDLATEC không chỉ điều trị bệnh mà còn hướng tới phát hiện sớm, dự phòng và cá thể hóa phương pháp điều trị cho từng người bệnh. Qua đó, giúp người dân chủ động hơn trong việc bảo vệ sức khỏe đường tiêu hóa và hạn chế tối đa các nguy cơ biến chứng nguy hiểm về lâu dài.&nbsp;Người dân có nhu cầu kiểm tra, thăm khám và điều trị các bệnh lý đường tiêu hóa nói riêng và bệnh lý đa chuyên khoa nói chung, vui lòng liên hệ tới MEDLATEC qua Tổng đài 1900 56 56 56 để được hỗ trợ kịp thời.&nbsp;&nbsp;</p>','2026-02-03 11:44:44.716062',0,'Nữ bệnh nhân 57 tuổi đi khám sức khỏe định kỳ tại MEDLATEC tình cờ phát hiện u dưới niêm mạc dạ dày và nhanh chóng được xử lý triệt để tổn thương ngay trong lần nội soi, tránh được phẫu thuật xâm lấn.','http://localhost:8080/api/images/articles/e810239f-4104-4de7-9684-8bb62a23f1b3.jpg',_binary '',_binary '\0','2026-02-03 11:44:57.384684','phat-hien-khoi-u','Tin tức y khoa','Phát hiện u dưới niêm mạc dạ dày khi khám định kỳ: MEDLATEC xử trí toàn diện, cắt bỏ an toàn bằng nội soi hiện đại','2026-02-03 11:44:57.385685','APPROVED',NULL,'medlatec'),(26,'Pham Long','<h2>Cảnh báo bệnh từ hút thuốc lá&nbsp;</h2><h2><br></h2><p>Bệnh viện Đa khoa MEDLATEC vừa tiếp nhận trường hợp của ông L.H.Q (66 tuổi, Nam) đến Bệnh viện Đa khoa MEDLATEC khám do khó thở khi gắng sức.&nbsp;</p><p>Chia sẻ với bác sĩ, bệnh nhân cho biết, khoảng 3 tháng trở lại đây, có xuất hiện các cơn&nbsp;</p><p>kh<a href=\"https://medlatec.vn/tu-dien-benh-ly/kho-tho-sropg\" rel=\"noopener noreferrer\" target=\"_blank\" style=\"color: rgb(29, 147, 227);\">ó thở</a></p><p>&nbsp;thường xuyên hơn, khó thở ngay cả khi đi bộ trên mặt phẳng, khả năng gắng sức giảm rõ rệt.&nbsp;</p><p>Mỗi khi xuất hiện cơn khó thở, bệnh nhân thường phải sử dụng thuốc xịt cắt cơn và có cải thiện tạm thời. Ngoài ra, bệnh nhân còn có biểu hiện ho khạc đờm trắng, khiến ông lo lắng và quyết định đi khám.&nbsp;</p><p class=\"ql-align-center\"><img src=\"https://medlatec.vn/media/68143/file/hut-thuoc-la-nhieu-nam.jpg\"></p><p class=\"ql-align-center\"><br></p><p class=\"ql-align-center\"><em>Hút thuốc lá nhiều năm làm tăng nguy cơ mắc bệnh phổi tắc nghẽn mạn tính. Ảnh minh họa, nguồn Internet</em></p><p><br></p><p>Khai thác tiền sử cho thấy, bệnh nhân có thói quen hút thuốc lá lâu năm, tương đương 40 bao.năm, hiện chưa cai thuốc. Trước đó khoảng 1 năm, bệnh nhân từng được chẩn đoán mắc bệnh phổi tắc nghẽn mạn tính (COPD), tuy nhiên chỉ sử dụng thuốc xịt khi lên cơn, chưa dùng thuốc ngừa đợt cấp. Trong vòng 1 năm qua, bệnh nhân chưa từng nhập viện vì khó thở.&nbsp;</p><p>Qua thăm khám lâm sàng, các chỉ số sinh tồn của bệnh nhân ổn định, SpO₂ đạt 98% khi thở khí trời, huyết áp bình thường 120/80 mmHg. Lồng ngực cân đối, hình thùng - một đặc điểm thường gặp ở bệnh nhân COPD lâu năm. Phổi giảm thông khí hai bên, không ghi nhận ran rít hay ran ngáy.&nbsp;</p><p>Đánh giá mức độ khó thở theo thang điểm mMRC, bệnh nhân đạt 2 điểm - đi bộ chậm hơn so với người cùng tuổi do khó thở, phù hợp với mô tả lâm sàng.&nbsp;</p><p>Kết quả&nbsp;</p><p>đo chức năng hô h<a href=\"https://medlatec.vn/tin-tuc/khi-nao-thi-chi-dinh-do-chuc-nang-ho-hap-va-khi-do-can-luu-y-nhung-gi-s64-n28641\" rel=\"noopener noreferrer\" target=\"_blank\" style=\"color: rgb(29, 147, 227);\">ấp</a></p><p>&nbsp;(hô hấp ký) cho thấy nhiều chỉ số suy giảm rõ rệt:&nbsp;</p><p>FVC</p><ul><li>&nbsp;(dung tích sống gắng sức): 3.0 lít (chiếm 76%), bình thường ≥ 80%, tức kết quả giảm, gợi ý rối loạn thông khí hạn chế.&nbsp;</li></ul><p>FEV1</p><ul><li>&nbsp;(thể tích thở ra gắng sức giây đầu): 1.36 lít (44%), bình thường ≥ 80%, tức kết quả giảm nặng, đánh giá mức độ tắc nghẽn đường thở.&nbsp;</li></ul><p>FEV1/FVC</p><ul><li>: 0.45 (bình thường &gt;=0.7), cho thấy kết quả giảm, khẳng định rối loạn thông khí tắc nghẽn.&nbsp;</li></ul><p>Dựa trên các chỉ số này, bác sĩ kết luận bệnh nhân bị rối loạn thông khí tắc nghẽn mức độ nặng, kèm theo theo dõi rối loạn thông khí hạn chế mức độ nhẹ.</p><p>Đáng lưu ý, kết quả chụp CT phổi ghi nhận hình ảnh: viêm phế quản mạn tính, giãn phế nang lan tỏa hai phổi - hình ảnh điển hình của COPD; ứ đọng dịch (đờm, nhầy) trong lòng khí quản.&nbsp;</p><p>Như vậy, dựa vào dấu hiệu lâm sàng và kết quả cận lâm sàng, bệnh nhân có chẩn đoán xác định mắc bệnh phổi tắc nghẽn mạn tính (COPD) - nhóm B.&nbsp;</p><p>Theo ThS.BS Mai Thị Ngân - Chuyên khoa Hô hấp, Bệnh viện Đa khoa MEDLATEC cho biết: Dựa vào đánh giá và phân nhóm COPD theo GOLD 2025 (phiên bản mới), bệnh phân thành 3 nhóm A-B-E, trong đó nhóm B là những bệnh nhân có triệu chứng khó thở đánh giá theo thang điểm mMRC ≥ 2, không có hoặc chỉ có 1 đợt cấp trong năm, chưa phải nhập viện trong năm vừa rồi. Những dấu hiệu chẩn đoán này hoàn toàn phù hợp với bệnh nhân Q.&nbsp;</p><p>Sau khi được chẩn đoán, bệnh nhân được bác sĩ kê đơn điều trị ngoại trú, thay đổi lối sống và hẹn tái khám định kỳ.&nbsp;</p><h2>Bệnh phổi tắc nghẽn mạn tính (COPD) là gì?&nbsp;</h2><p><img src=\"https://medlatec.vn/media/68144/file/benh-phoi-tac-nghen-man-tinh.jpg\"></p><p><br></p><p class=\"ql-align-center\">Bệnh phổi tắc nghẽn mạn tính là tì<em>nh trạng tắc nghẽn đường không hồi phục. Ảnh minh họa</em>, nguồn Internet</p><p><br></p><p>Bệnh phổi tắc nghẽn mạn tính (COPD), đặc trưng bởi tình trạng tắc nghẽn đường thở không hồi phục, tiến triển tăng dần theo thời gian. Nguyên nhân thường gặp gồm:&nbsp;</p><p>Hút thuốc lá (chủ động hoặc thụ động);&nbsp;</p><ul><li>Viêm phế quản mạn tính kéo dài;&nbsp;</li><li>Khí phế thủng gây giãn phế nang, mất đàn hồi phổi.&nbsp;</li></ul><p>Triệu chứng điển hình của COPD là khó thở và ho mạn tính, đặc biệt khi gắng sức. Tiêu chí chẩn đoán quan trọng là FEV1/FVC &lt; 0,7 sau test hồi phục phế quản.&nbsp;</p><p>Sự khác biệt giữa hen phế quản và COPD&nbsp;</p><p>Theo bác sĩ Ngân, sự khác biệt giữa hen phế quản và COPD dựa trên những đặc điểm sau:</p><ul><li>Hen phế quản là tình trạng viêm và co thắt phế quản có hồi phục, trong khi COPD gây chít hẹp đường thở không hồi phục.</li><li>Thuốc corticoid dạng hít (ICS) đóng vai trò quan trọng trong kiểm soát hen, nhưng không có vai trò nhiều trong COPD. Bệnh COPD thuốc duy trì điều trị quan trọng nhất LAMA và LABA.&nbsp;</li></ul><p>Đánh giá mức độ khó thở theo thang điểm mMRC&nbsp;</p><p>Đánh giá mức độ khó thở ở bệnh nhân COPD theo thang điểm mMRC (Modified Medical Research Council) phân làm 5 mức độ sau:&nbsp;</p><p>Mức độ 0:</p><p>&nbsp;Chỉ bị khó thở khi gắng sức nhiều.&nbsp;</p><p>Mức độ 1:</p><p>&nbsp;Bị hụt hơi khi đi nhanh trên mặt phẳng hoặc khi leo dốc.&nbsp;</p><p>Mức độ 2</p><ul><li>: Trên mặt phẳng, đi chậm hơn so với người cùng tuổi vì khó thở, hoặc phải dừng lại để thở khi đi với người cùng tuổi trên đường bằng.&nbsp;</li></ul><p>Mức độ 3</p><ul><li>: Phải dừng lại để thở sau khi đi khoảng 100 mét hoặc sau vài phút đi trên mặt phẳng.&nbsp;</li></ul><p>Mức độ 4</p><ul><li>: Khó thở nhiều đến mức không thể ra khỏi nhà, hoặc khó thở ngay cả khi thay quần áo.&nbsp;</li></ul><p>Trường hợp bệnh nhân L.H.Q, đánh giá mMRC = 2 điểm là phù hợp với mô tả lâm sàng (khó thở khi đi bộ đường bằng, giảm khả năng gắng sức).&nbsp;</p><p>Cách điều trị và phòng ngừa COPD&nbsp;</p><p>Sau khi có chẩn đoán xác định, bệnh nhân được tư vấn điều trị ngoại trú; Cai thuốc lá hoàn toàn; Tiêm phòng cúm, phế cầu, RSV, ho gà; Tầm soát các bệnh lý khác đi kèm.&nbsp;Bên cạnh đó, bác sĩ dặn dò bệnh nhân:&nbsp;</p><p>Tránh khói thuốc, khói bụi, môi trường ô nhiễm và gió lạnh;&nbsp;</p><p>Không uống nước lạnh;&nbsp;</p><ul><li>Tập thở cơ hoành, vận động thể lực phù hợp;&nbsp;</li><li>Dùng thuốc đúng chỉ định, tái khám khi hết thuốc hoặc khi có triệu chứng bất thường.&nbsp;</li></ul><p>COPD là bệnh mạn tính không thể chữa khỏi hoàn toàn, nhưng hoàn toàn có thể kiểm soát tốt nếu được phát hiện sớm và điều trị đúng cách. Việc cai thuốc lá chính là “chìa khóa vàng” giúp làm chậm tiến triển bệnh và cải thiện chất lượng cuộc sống cho người bệnh.&nbsp;</p><p><img src=\"https://medlatec.vn/media/68145/file/chuyen-gia-ho-hap-medlatec.webp\"></p><p><br></p><p class=\"ql-align-center\">Chuyên gia Hô hấp đang thực hiện lấy mẫu làm xét nghiệm chẩn đoán chuyên sâu tại<em> Hệ thống </em>Y tế MEDLATEC</p><p><br></p><p>Sở hữu thế mạnh đơn vị y tế có 30 năm kinh nghiệm, quy tụ đội ngũ chuyên gia Hô hấp giàu kinh nghiệm, cùng đội ngũ y bác sĩ đa chuyên khoa đầu ngành, y đức và trang bị đồng bộ hệ thống máy móc hiện đại như: máy đo chức năng hô hấp, CT, MRI, Trung tâm Xét nghiệm hiện đại bậc nhất… Vì vậy, Hệ thống Y tế MEDLATEC có năng lực tốt nhất đáp ứng toàn diện nhu cầu khám và chẩn đoán các bệnh hô hấp nói chung, tầm soát, phát hiện sớm và theo dõi điều trị các bệnh phổi mạn tính cũng như cấp tính.</p><p>Hệ thống Y tế MEDLATEC cung cấp dịch vụ khám và chẩn đoán toàn diện các bệnh lý hô hấp, đáp ứng nhu cầu tầm soát, phát hiện sớm và theo dõi điều trị các bệnh phổi mạn tính cũng như cấp tính.</p><p>Người dân an tâm được thăm khám trực tiếp bởi đội ngũ bác sĩ chuyên khoa Hô hấp giàu kinh nghiệm, tuân thủ các hướng dẫn chẩn đoán và điều trị mới nhất theo khuyến cáo quốc tế. Sau khi có kết quả chẩn đoán, người dân được tư vấn, quản lý và cá thể hóa phác đồ điều trị để nâng cao hiệu quả dự phòng, điều trị cũng như chất lượng cuộc sống.&nbsp;</p><p>Thông tin chi tiết tìm hiểu về dịch vụ khám chữa bệnh tại Hệ thống Y tế MEDLATEC, người dân vui lòng liên hệ tổng đài: 1900 56 56 56.&nbsp;</p>','2026-02-04 13:00:55.544807',0,'Có thói quen hút thuốc lá nhiều năm, khoảng 3 tháng nay, người đàn ông xuất hiện các cơn khó thở nhiều hơn, khó thở ngay khi đi bộ đường bằng, khả năng gắng sức giảm nên đến Bệnh viện Đa khoa MEDLATEC thăm khám. Kết quả khám chẩn đoán bệnh phổi tắc nghẽn mạn tính nhóm B.','http://localhost:8080/api/images/articles/a5d2dde2-3aaf-4d7b-95c4-5d9bd4ce964b.jpg',_binary '\0',_binary '\0','2026-02-04 13:00:55.544807','hut-thuoc-la-nhieu-nam','Tin tức y khoa','Hút thuốc lá nhiều năm, xuất hiện khó thở, đi khám phát hiện bệnh phổi tắc nghẽn mạn tính','2026-02-04 13:00:55.603108','APPROVED',7,'medlatec'),(31,'Pham Long','<h2 class=\"ql-align-justify\">Nữ bệnh nhân phát hiện sớm ung thư vú nhờ mô hình chẩn đoán liên thông</h2><p class=\"ql-align-justify\">Bệnh nhân nữ, 48 tuổi, ở Hà Tĩnh tình cờ phát hiện tổn thương ở vú khi khám sức khỏe tổng quát. Sau đó, chị đã đến thăm khám chuyên sâu tại phòng khám BSCKI. Đào Văn Hùng.</p><p class=\"ql-align-justify\">Qua siêu âm tuyến vú, bác sĩ Hùng phát hiện nhân tuyến vú trái có đặc điểm hình thái bất thường, được phân loại BI-RADS 4.</p><p class=\"ql-align-justify\">Bằng kinh nghiệm lâm sàng dày dặn, bác sĩ Hùng nhận định đây là tổn thương nghi ngờ ác tính cao. Bệnh nhân được chỉ định chọc hút tế bào bằng kim nhỏ (FNA) ngay tại phòng khám.</p><p class=\"ql-align-justify\">Mẫu bệnh phẩm sau khi lấy được chuyển về Trung tâm Giải phẫu bệnh MEDLATEC để phân tích chuyên sâu với quy trình được thực hiện nghiêm ngặt theo tiêu chuẩn quốc tế:</p><ul><li class=\"ql-align-justify\">Cố định mẫu: Đảm bảo hình thái tế bào nguyên vẹn, không bị biến dạng.</li><li class=\"ql-align-justify\">Kỹ thuật nhuộm Giemsa: Giúp làm nổi bật các đặc điểm nhân và bào tương của tế bào ác tính.</li><li class=\"ql-align-justify\">Áp dụng hệ thống phân loại Yokohama 2019: Đây là tiêu chuẩn quốc tế mới nhất trong báo cáo tế bào học tuyến vú, giúp chuẩn hóa ngôn ngữ chẩn đoán giữa bác sĩ giải phẫu bệnh và bác sĩ lâm sàng.</li></ul><p class=\"ql-align-center\"><img src=\"https://medlatec.vn/media/67918/file/1-xet-nghiem-te-bao-hoc.png\"></p><p class=\"ql-align-center\"><em>Kết quả xét nghiệm tế bào học cho thấy đây là tổn thương ác tính</em></p><p class=\"ql-align-justify\">Xét nghiệm tế bào học tại MEDLATEC kết luận đây là tổn thương ác tính (nhóm V theo phân loại Yokohama 2019), phù hợp với&nbsp;<a href=\"https://medlatec.vn/tin-tuc/ung-thu-la-benh-gi-nguyen-nhan-ung-thu-bat-nguon-tu-dau-s91-n30574\" rel=\"noopener noreferrer\" target=\"_blank\" style=\"color: rgb(29, 147, 227);\">ung thư</a>&nbsp;biểu mô tuyến vú. Kết quả này là \"chìa khóa” giúp bác sĩ lâm sàng có cơ sở vững chắc để xây dựng chiến lược can thiệp và điều trị chuyên sâu cho người bệnh.</p><h2 class=\"ql-align-justify\">Tầm quan trọng của xét nghiệm tế bào học trong chẩn đoán ung thư vú</h2><p class=\"ql-align-center\"><img src=\"https://medlatec.vn/media/67919/file/2-trung-tam-giai-phau-benh.png\"></p><p class=\"ql-align-center\"><em>Xét nghiệm tế bào học đóng vai trò quan trọng giúp phát hiện sớm các bất thường</em></p><p class=\"ql-align-justify\">Trong quy trình tầm soát và chẩn đoán ung thư vú, xét nghiệm tế bào học (Cytology) đóng vai trò quan trọng giúp phát hiện sớm các bất thường. Theo ThS.BSNT Trương Quốc Thanh – Quyền Giám đốc Trung tâm Giải phẫu bệnh MEDLATEC, đây là phương pháp cận lâm sàng dựa trên việc thu thập, xử lý và phân tích hình thái tế bào dưới kính hiển vi để tìm kiếm các dấu hiệu bệnh lý.</p><p class=\"ql-align-justify\">Mẫu bệnh phẩm tế bào có thể được thu thập bằng nhiều kỹ thuật khác nhau, trong đó phổ biến nhất trong bệnh lý tuyến vú gồm: chọc hút tế bào bằng kim nhỏ (Fine Needle Aspiration Cytology – FNAC); lấy tế bào từ dịch tiết núm vú hoặc các dịch cơ thể liên quan.</p><p class=\"ql-align-justify\">So với sinh thiết mô, xét nghiệm tế bào học là phương pháp ít xâm lấn, an toàn, chi phí thấp, thời gian thực hiện nhanh và có thể lặp lại nhiều lần. Nhờ những ưu điểm này, tế bào học đặc biệt phù hợp trong đánh giá ban đầu các khối u vú nghi ngờ, hỗ trợ sàng lọc và định hướng chẩn đoán.</p><p class=\"ql-align-justify\">Kết quả xét nghiệm tế bào học giúp phân loại tổn thương theo hướng lành tính, nghi ngờ hoặc ác tính; từ đó định hướng chỉ định sinh thiết mô học, phẫu thuật hoặc theo dõi, đồng thời hạn chế các can thiệp không cần thiết đối với các tổn thương lành tính.</p><p class=\"ql-align-justify\">Trong thực hành lâm sàng, xét nghiệm tế bào học thường được sử dụng phối hợp với thăm khám lâm sàng và các phương tiện chẩn đoán hình ảnh như: siêu âm, nhũ ảnh. Sự tương quan của ba yếu tố này, còn gọi là “Triple test”, góp phần nâng cao độ chính xác trong chẩn đoán&nbsp;<a href=\"https://medlatec.vn/tu-dien-benh-ly/ung-thu-vu-sIbsZ\" rel=\"noopener noreferrer\" target=\"_blank\" style=\"color: rgb(29, 147, 227);\">ung thư vú</a>, là cơ sở quan trọng để bác sĩ lâm sàng đưa ra quyết định can thiệp kịp thời, phù hợp cho người bệnh.</p><h2 class=\"ql-align-justify\">MEDLATEC – Kết nối y tế tuyến cơ sở với chẩn đoán chuyên sâu</h2><p class=\"ql-align-center\"><img src=\"https://medlatec.vn/media/67920/file/3-trung-tam-giai-phau-benh.png\"></p><p class=\"ql-align-center\"><em>MEDLATEC là đối tác của hơn 17.000 bác sĩ, phòng khám, các bệnh viện hàng đầu trên khắp cả nước, cùng nhau thúc đẩy và phát triển dịch vụ y tế chất lượng cao</em></p><p class=\"ql-align-justify\">Từ trường hợp nữ bệnh nhân nêu trên có thể thấy rằng, việc phát hiện sớm ung thư không phụ thuộc vào khoảng cách địa lý, mà được quyết định bởi sự đồng bộ của nhiều yếu tố then chốt, bao gồm:&nbsp;</p><ul><li class=\"ql-align-justify\">Năng lực phát hiện ban đầu của bác sĩ chẩn đoán hình ảnh; chỉ định kịp thời và phù hợp các thủ thuật xâm lấn tối thiểu;</li><li class=\"ql-align-justify\">Hệ thống giải phẫu bệnh có chuyên môn sâu, được chuẩn hóa;</li><li class=\"ql-align-justify\">Mô hình kết nối hiệu quả giữa tuyến y tế cơ sở và các trung tâm chuyên môn.</li></ul><p class=\"ql-align-justify\">Khi các yếu tố này được phối hợp nhịp nhàng, người bệnh tại tuyến tỉnh hoàn toàn có thể tiếp cận chất lượng chẩn đoán tương đương tuyến trung ương.</p><p class=\"ql-align-center\"><img src=\"https://medlatec.vn/media/67921/file/4-trung-tam-giai-phau-benh.jpg\"></p><p class=\"ql-align-center\"><em>Các chuyên gia hội chẩn ca bệnh khó tại Trung tâm Giải phẫu bệnh MEDLATEC</em></p><p class=\"ql-align-justify\">Với định hướng phát triển y tế dựa trên sự liên thông chuyên môn và chuẩn hóa chất lượng chẩn đoán, Hệ thống Y tế MEDLATEC đã xây dựng một hệ sinh thái chẩn đoán toàn diện. Đây chính là điểm tựa vững chắc để các bác sĩ tuyến cơ sở và người dân hoàn toàn an tâm khi khám, tầm soát sớm các bệnh lý, trong đó có ung thư vú, thông qua những năng lực vượt trội sau:</p><ul><li class=\"ql-align-justify\">Quy tụ đội ngũ chuyên gia, bác sĩ đầu ngành lĩnh vực Ung bướu, Chẩn đoán hình ảnh, Giải phẫu bệnh, Xét nghiệm;</li><li class=\"ql-align-justify\">Là đơn vị y tế đầu tiên sở hữu dịch vụ xét nghiệm đạt Thương hiệu Quốc gia Việt Nam và tiên phong quản lý chất lượng xét nghiệm bằng hai tiêu chuẩn quốc tế song hành CAP, ISO 15189:2022.</li><li class=\"ql-align-justify\">Trung tâm Giải phẫu bệnh ứng dụng công nghệ số hóa và hội chẩn từ xa, có năng lực đáp ứng hơn 150.000 xét nghiệm mỗi năm, bao gồm: tế bào học, mô bệnh học, hóa mô miễn dịch và đột biến gen. Thời gian trả kết quả nhanh, kịp thời để phục vụ tối đa nhu cầu chẩn đoán chính xác các bệnh lý u, nghi ngờ u.</li><li class=\"ql-align-justify\">Mô hình Trung tâm Chẩn đoán hình ảnh “không khoảng cách”, đáp ứng chẩn đoán hình ảnh từ xa, nhanh chóng, chính xác. Hệ thống thiết bị đồng bộ, hiện đại như: máy MRI, CT/MSCT, máy X-quang, máy chụp cắt lớp vi tính, Fibroscan, siêu âm.</li><li class=\"ql-align-justify\">Mạng lưới rộng khắp toàn quốc với: 01 Bệnh viện, 41 Phòng khám tại Việt Nam, 01 Phòng khám tại Campuchia, hơn 100 văn phòng lấy mẫu tận nơi. Nhờ đó, các cơ sở y tế địa phương có thể gửi mẫu nhanh chóng, nhận kết quả chính xác, hỗ trợ bác sĩ lâm sàng ra quyết định kịp thời.</li></ul><p class=\"ql-align-justify\">Mọi thông tin chi tiết, người dân vui lòng liên hệ tổng đài MEDLATEC&nbsp;</p><p class=\"ql-align-justify\">1<strong>900 56 56 56</strong></p><p class=\"ql-align-justify\">.&nbsp;</p>','2026-02-04 11:55:07.026164',0,'Trường hợp một phụ nữ phát hiện sớm ung thư vú khi đi khám tại một phòng khám ở Hà Tĩnh mới đây cho thấy hiệu quả của mô hình kết nối tuyến y tế cơ sở với hệ thống chẩn đoán chuyên sâu. Điều này giúp người bệnh tiết kiệm thời gian, chi phí, hỗ trợ bác sĩ lâm sàng ra quyết định điều trị kịp thời.','http://localhost:8080/api/images/articles/839d54fb-5fcd-42db-97f0-f598e7d69ed8.png',_binary '',_binary '\0','2026-02-04 11:55:34.900881','trung-tam-giai-phau-benh-medlatec-phoi-hop-cung-bac-si-tuyen-co-so-phat-hien-som-ca-benh-ung-thu-vu','Tin tức y khoa','Trung tâm Giải phẫu bệnh MEDLATEC phối hợp cùng bác sĩ tuyến cơ sở phát hiện sớm ca bệnh ung thư vú','2026-02-04 11:55:34.903085','APPROVED',7,'medlatec'),(32,'Pham Long','<h2 class=\"ql-align-justify\">Tuổi cao không đồng nghĩa với “miễn nhiễm” ung thư&nbsp;vú&nbsp;&nbsp;</h2><p class=\"ql-align-justify\">Vừa qua, Bệnh viện Đa khoa MEDLATEC tiếp nhận bà N.A.T (75 tuổi) đến thăm khám trong tình trạng có khối u tại&nbsp;vú&nbsp;trái. Bà T. cho biết, bản thân chỉ nghĩ đơn giản đó là những thay đổi lão hóa tự nhiên của tuổi già.&nbsp;</p><p class=\"ql-align-justify\">Tại MEDLATEC,&nbsp;bệnh nhân được TTND.PGS.TS.BSCC&nbsp;Đoàn Hữu Nghị - Nguyên Giám đốc Bệnh viện E, Nguyên Phó Giám đốc Bệnh viện K, Phó Chủ tịch Hội&nbsp;<a href=\"https://medlatec.vn/tin-tuc/ung-thu-la-benh-gi-nguyen-nhan-ung-thu-bat-nguon-tu-dau-s91-n30574\" rel=\"noopener noreferrer\" target=\"_blank\" style=\"color: rgb(29, 147, 227);\">ung thư</a>&nbsp;Hà Nội,&nbsp;Chuyên gia Ung bướu tại Hệ thống Y tế MEDLATEC – trực tiếp thăm khám và chỉ đạo chẩn đoán.&nbsp;</p><p class=\"ql-align-justify\">Bằng kinh nghiệm lâm sàng dày dạn, PGS.TS Đoàn Hữu Nghị nhận định đây là tổn thương nghi ngờ ác tính cao và chỉ định thực hiện các chẩn đoán cận lâm sàng chuyên sâu để \"truy vết\" bản chất khối u.&nbsp;</p><p class=\"ql-align-justify\">Chụp X-quang tuyến&nbsp;vú&nbsp;kỹ thuật số (Mammography)&nbsp;phát hiện&nbsp;nốt tăng đậm độ nhu mô&nbsp;vú&nbsp;trái, phân loại BIRADS 5.&nbsp;</p><p class=\"ql-align-justify\">Trên siêu âm tuyến&nbsp;vú&nbsp;cho thấy hình ảnh nhân tuyến&nbsp;vú&nbsp;trái (BIRADS 5), kèm hạch hố nách hai bên.&nbsp;</p><p class=\"ql-align-justify\">Kết quả chụp CT lồng ngực&nbsp;ghi nhận hình ảnh khối u tuyến&nbsp;vú&nbsp;trái.&nbsp;</p><p class=\"ql-align-center\"><img src=\"https://medlatec.vn/media/67823/file/ung-thu-vu-1.png\"></p><p class=\"ql-align-center\"><em>Chụp X-quang tuyến&nbsp;vú&nbsp;ghi nhận nốt tăng đậm độ nhu mô&nbsp;vú&nbsp;trái, phân loại BIRADS 5&nbsp;</em></p><p class=\"ql-align-center\"><img src=\"https://medlatec.vn/media/67824/file/ung-thu-vu.png\"></p><p class=\"ql-align-center\"><em>Trên siêu âm cho thấy hình ảnh nhân tuyến&nbsp;vú&nbsp;trái (BIRADS 5), kèm hạch hố nách hai bên&nbsp;</em></p><p class=\"ql-align-justify\">Để xác định chính xác bản chất tổn thương, PGS. Nghị đã chỉ định thực hiện sinh thiết dưới hướng dẫn của siêu âm. Mẫu bệnh phẩm nhanh chóng được chuyển tới Trung tâm Giải phẫu bệnh MEDLATEC để phân tích chuyên sâu.&nbsp;</p><p class=\"ql-align-justify\">Kết quả xét nghiệm mô bệnh học thường quy (nhuộm Hematoxylin - Eosin)&nbsp;xác định&nbsp;bệnh nhân mắc Carcinoma tuyến&nbsp;vú&nbsp;thể ống xâm nhập (NST), độ&nbsp;mô học&nbsp;II.&nbsp;&nbsp;</p><p class=\"ql-align-center\"><img src=\"https://medlatec.vn/media/67827/file/ung-thu-vu-gpb.png\"></p><p class=\"ql-align-center\"><em>Xét nghiệm mô bệnh học xác định bệnh nhân mắc&nbsp;Carcinoma tuyến&nbsp;vú&nbsp;thể ống xâm nhập</em></p><p class=\"ql-align-justify\">Tuy nhiên, để đánh giá chính xác tiên lượng và xây dựng phác đồ&nbsp;điều&nbsp;trị&nbsp;tối&nbsp;ưu,&nbsp;cần&nbsp;thực&nbsp;hiện&nbsp;thêm&nbsp;xét&nbsp;nghiệm&nbsp;hóa&nbsp;mô&nbsp;miễn&nbsp;dịch&nbsp;(HMMD)&nbsp;với&nbsp;bộ&nbsp;4&nbsp;dấu&nbsp;ấn&nbsp;đặc&nbsp;hiệu&nbsp;(ER, PR, HER-2, Ki-67).&nbsp;Kết&nbsp;quả&nbsp;đây&nbsp;là&nbsp;Carcinoma&nbsp;tuyến&nbsp;vú&nbsp;xâm&nbsp;nhập,&nbsp;phân&nbsp;típ&nbsp;phân&nbsp;tử&nbsp;lòng&nbsp;ống&nbsp;B (Luminal B), HER-2&nbsp;dương&nbsp;tính&nbsp;3+.&nbsp;&nbsp;</p><p class=\"ql-align-center\"><img src=\"https://medlatec.vn/media/67828/file/ung-thu-vu-hmmd.png\"></p><p class=\"ql-align-center\"><em>Xét&nbsp;nghiệm&nbsp;hóa&nbsp;mô&nbsp;miễn&nbsp;dịch cho kết quả&nbsp;Carcinoma&nbsp;tuyến&nbsp;vú&nbsp;xâm&nbsp;nhập,&nbsp;phân&nbsp;típ&nbsp;phân&nbsp;tử&nbsp;lòng&nbsp;ống&nbsp;B (Luminal B), HER-2&nbsp;dương&nbsp;tính&nbsp;3+</em></p><p class=\"ql-align-justify\">Căn cứ&nbsp;vào kết quả trên,&nbsp;bác sĩ chẩn đoán&nbsp;bà&nbsp;T.&nbsp;mắc&nbsp;ung thư&nbsp;tuyến vú&nbsp;biểu mô thể ống xâm nhập, độ mô học II.&nbsp;&nbsp;</p><p class=\"ql-align-justify\">Với kết quả&nbsp;mô&nbsp;bệnh học và&nbsp;HMMD thực hiện&nbsp;tại MEDLATEC, các bác sĩ&nbsp;đã&nbsp;có&nbsp;đầy&nbsp;đủ&nbsp;căn cứ&nbsp;để lựa chọn thuốc điều trị đích&nbsp;hiệu quả nhất.&nbsp;Hiện tại bệnh nhân&nbsp;đã&nbsp;truyền&nbsp;hóa&nbsp;chất&nbsp;3&nbsp;đợt,&nbsp;đáp ứng tốt,&nbsp;<a href=\"https://medlatec.vn/tin-tuc/khoi-u-trong-co-the-hinh-thanh-do-dau-xu-ly-the-nao-s91-n31441\" rel=\"noopener noreferrer\" target=\"_blank\" style=\"color: rgb(29, 147, 227);\">khối u</a>&nbsp;nhỏ&nbsp;hơn 50% so với thời điểm khám.&nbsp;</p><h2 class=\"ql-align-justify\">Giải phẫu bệnh: \"Tiêu chuẩn vàng\" giúp giải mã bản chất và cá thể hóa&nbsp;điều trị&nbsp;khối u&nbsp;</h2><p class=\"ql-align-center\"><img src=\"https://medlatec.vn/media/67826/file/trung-tam-giai-phau-benh-medlatec-2025-1.jpg\"></p><p class=\"ql-align-center\"><em>Trung tâm Giải phẫu bệnh MEDLATEC thực hiện đầy đủ các xét nghiệm về&nbsp;mô bệnh học và&nbsp;hóa mô miễn dịch&nbsp;</em></p><p class=\"ql-align-justify\">Theo&nbsp;PGS Đoàn Hữu Nghị,&nbsp;ung thư&nbsp;tuyến&nbsp;vú&nbsp;xâm nhập là ung thư&nbsp;vú&nbsp;thường gặp nhất, có khả năng tiến triển và di căn nếu không được phát hiện kịp thời.&nbsp;</p><p class=\"ql-align-justify\">Nếu Chẩn đoán hình ảnh (siêu âm, X-quang, MRI) giúp bác sĩ \"nhìn thấy\" khối u, thì Giải phẫu bệnh giúp bác sĩ \"thấu hiểu\" khối&nbsp;u.&nbsp;Tầm quan trọng của chuyên khoa này được thể hiện rõ qua các khía cạnh:&nbsp;</p><ul><li class=\"ql-align-justify\">Xác định bản chất thực sự: Phân biệt chính xác giữa khối u lành tính và ác tính (ung thư);&nbsp;</li><li class=\"ql-align-justify\">Định danh loại mô học: Ung thư&nbsp;vú&nbsp;không chỉ có một loại. Giải phẫu bệnh giúp xác định là ung thư biểu mô ống hay thùy, từ đó dự báo mức độ xâm lấn;&nbsp;</li><li class=\"ql-align-justify\">Xác định \"đặc tính sinh học\" (Hóa mô miễn dịch): Đây là bước tiến hiện đại giúp xác định các thụ thể nội tiết (ER, PR) hay protein HER2;&nbsp;</li><li class=\"ql-align-justify\">Đánh giá mức độ ác tính (Grading): Cho biết tế bào ung thư phát triển nhanh hay chậm, giúp tiên lượng khả năng tái phát.&nbsp;</li></ul><p class=\"ql-align-justify\">Ở người cao tuổi, các triệu chứng ung thư&nbsp;vú&nbsp;thường diễn tiến âm thầm, dễ bị nhầm lẫn hoặc bỏ sót. Việc thực hiện sinh thiết và xét nghiệm giải phẫu bệnh không chỉ giúp phát hiện sớm mà còn là tiền đề để xây dựng chiến lược \"điều trị&nbsp;trúng đích\".&nbsp;</p><p class=\"ql-align-justify\">Sự nhạy bén của các chuyên gia kết hợp với kết quả giải phẫu bệnh chính xác,&nbsp;giúp bệnh nhân tránh được các tác dụng phụ không mong muốn từ những liệu pháp không phù hợp.&nbsp;</p><h2 class=\"ql-align-justify\">Địa chỉ uy tín khám, tầm soát ung thư vú&nbsp;</h2><p class=\"ql-align-center\"><img src=\"https://medlatec.vn/media/67825/file/chuyen-gia-doan-huu-nghi-3-1.jpg\"></p><p class=\"ql-align-center\"><em>TTND.PGS.TS.BSCC&nbsp;Đoàn Hữu Nghị là một trong những chuyên gia đầu ngành chuyên khoa Ung bướu&nbsp;</em></p><p class=\"ql-align-justify\">Trường hợp ca bệnh trên&nbsp;tiếp tục khẳng định năng lực chẩn đoán chuyên sâu và mô hình đa chuyên khoa hiệu quả tại Hệ thống Y tế MEDLATEC.&nbsp;</p><p class=\"ql-align-justify\">Bằng sự nhạy bén trong lâm sàng, hệ thống trang thiết bị hiện đại,&nbsp;cùng việc phối hợp chặt chẽ&nbsp;giữ các&nbsp;chuyên khoa&nbsp;(Lâm sàng – Xét nghiệm – Chẩn đoán hình ảnh – Giải phẫu bệnh), các bác sĩ&nbsp;đã&nbsp;xác định chính xác đặc tính sinh học, mức độ ác tính&nbsp;của khối u,&nbsp;từ đó&nbsp;đánh giá chính xác tiên lượng và xây dựng phác đồ&nbsp;điều trị&nbsp;tối ưu cho bệnh nhân.&nbsp;</p><p class=\"ql-align-justify\">Lựa chọn thăm khám, tầm soát ung thư&nbsp;vú&nbsp;tại MEDLATEC, người dân hoàn toàn an tâm bởi sở hữu những năng lực vượt trội sau:&nbsp;</p><ul><li class=\"ql-align-justify\">Quy tụ đội ngũ chuyên gia, bác sĩ đầu ngành lĩnh vực Ung bướu, Chẩn đoán hình ảnh, Giải phẫu bệnh, Xét nghiệm;&nbsp;&nbsp;</li><li class=\"ql-align-justify\">Là đơn vị y tế đầu tiên sở hữu dịch vụ xét nghiệm đạt Thương hiệu Quốc gia Việt Nam và tiên phong quản lý chất lượng xét nghiệm bằng hai tiêu chuẩn quốc tế song hành CAP, ISO 15189:2022.&nbsp;&nbsp;</li><li class=\"ql-align-justify\">Mô hình Trung tâm Chẩn đoán hình ảnh “không khoảng cách”, đáp ứng chẩn đoán hình ảnh từ xa, nhanh chóng, chính xác. Hệ thống thiết bị đồng bộ, hiện đại như máy MRI, CT/MSCT, máy X-quang, máy chụp cắt lớp vi tính, Fibroscan, siêu âm.&nbsp;</li><li class=\"ql-align-justify\">Trung tâm Giải phẫu bệnh có năng lực đáp ứng hơn 150.000 xét nghiệm mỗi năm gồm: tế bào học, mô bệnh học, hóa mô miễn dịch và đột biến gen. Thời gian trả kết quả nhanh, kịp thời để phục vụ tối đa nhu cầu chẩn đoán chính xác các bệnh lý u, nghi ngờ u.&nbsp;&nbsp;</li></ul><p class=\"ql-align-justify\">Người dân vui lòng liên hệ tổng đài MEDLATEC&nbsp;<strong>1900 56 56 56</strong>&nbsp;để được hỗ trợ đặt lịch thăm khám/ xét nghiệm kịp thời.&nbsp;</p><p><br></p>','2026-02-04 11:57:25.879232',0,'Nhiều người vẫn lầm tưởng rằng ung thư vú chỉ gặp ở phụ nữ trung niên, tuy nhiên thực tế cho thấy bệnh có thể xuất hiện ở mọi độ tuổi. Trường hợp bệnh nhân nữ 75 tuổi được chẩn đoán ung thư vú tại MEDLATEC là một minh chứng rõ ràng cho điều đó.','http://localhost:8080/api/images/articles/5bcb35b8-7b01-45be-acfd-c8bd285aae5b.png',_binary '',_binary '\0','2026-02-04 11:57:41.975629','chu-quan-khoi-u-o-tuoi-gia-cu-ba-75-tuoi-phat-hien-ung-thu-vu-giai-doan-xam-nhap','Tin tức y khoa','Chủ quan khối u ở tuổi già, cụ bà 75 tuổi phát hiện ung thư vú giai đoạn xâm nhập','2026-02-04 11:57:41.976627','APPROVED',7,'medlatec'),(33,'Pham Long','<h2>Uống, bôi thuốc ngứa không khỏi, nam sinh đi khám phát hiện nguyên nhân do ký sinh trùng&nbsp;</h2><h2><br></h2><p>Đó là trường hợp của cháu C.L (16 tuổi, ở Bắc Ninh) đến Phòng khám Đa khoa MEDLATEC Bắc Ninh khám trong tình trạng sẩn ngứa kéo dài hơn 1 năm.&nbsp;</p><p>Một tháng trở lại đây, trước tình trạng ngứa tăng nhiều hơn nên gia đình được tư vấn xét nghiệm bộ giun sán tại nhà cho cháu L.&nbsp;</p><p>Kết quả xét nghiệm tại nhà có chỉ số&nbsp;</p><p>sán dây</p><p>&nbsp;chó dương tính và sán dây lợn nghi ngờ. Ngay khi có kết quả xét nghiệm, bác sĩ MEDLATEC gọi điện tư vấn, khuyên cháu L. đi kiểm tra chuyên sâu để tìm nguyên nhân chính xác.&nbsp;</p><p>Cháu L. chia sẻ, bị sẩn ngứa 1 năm nay, tổn thương dạng sẩn cục tập trung nhiều vùng cổ, ngoài ra có rải rác ở cẳng tay, cẳng chân. Trước tình trạng ngứa kéo dài, gia đình đưa cháu L. đi khám thì được chẩn đoán&nbsp;</p><p>viêm da cơ địa</p><p>. Cháu được điều trị bằng thuốc uống và thuốc bôi, tình trạng sẩn ngứa có thuyên giảm, nhưng chưa khỏi hẳn.&nbsp;</p><p>Gia đình chưa phát hiện có ai mắc bệnh lý liên quan, nhà có nuôi chó và có thói quen ăn rau sống, nhưng không có thói quen tẩy giun định kỳ.&nbsp;</p><p>Tại Phòng khám Đa khoa MEDLATEC Bắc Ninh, bác sĩ khám các chỉ số sinh tồn của cháu L. bình thường, có nhiều tổn thương dạng sẩn cục trên da vùng cổ, có nhiều sẹo cũ ở da cẳng chân và cẳng tay hai bên.</p><p><img src=\"https://medlatec.vn/media/67678/file/ngua-medlatec.jpg\"></p><p><br></p><p>Hình ảnh tổn thương dạng sẩn cục trên da vùng cổ của cháu L.</p><p><br></p><p>Dựa trên kết quả xét nghiệm đã có và tình trạng lâm sàng, bác sĩ chỉ định bệnh nhân thực hiện thêm một số xét nghiệm và&nbsp;</p><p>siêu âm</p><p>&nbsp;ổ bụng.</p><p>Kết quả xét nghiệm IgE máu tăng, tăng nhẹ bạch cầu ái toan, vi nấm soi tươi âm tính. Siêu âm ổ bụng chưa phát hiện bất thường. Chụp X-quang tim phổi có hình ảnh nốt mờ vùng ngoại vi rốn phổi phải (theo dõi nốt viêm cũ).&nbsp;</p><p>Bác sĩ chẩn đoán xác định bệnh nhân nhiễm sán dây chó / sẩn ngứa và được tư vấn điều trị ngoại trú, cũng như hướng dẫn cách chăm sóc da và tái khám theo lịch.&nbsp;</p><p><img src=\"https://medlatec.vn/media/67681/file/hinh-anh-sau-tai-kham.png\"></p><p><br></p><p>Sau 1 tháng điều trị, các tổn thương trên da vùng cổ đã hết các sẩn cục, hết ngứa, chỉ còn tổn thương dạng sẹo cũ</p><p><br></p><p>Tái khám sau 1 tháng điều trị, xét nghiệm IgE máu giảm; số lượng bạch cầu ái toan trở về bình thường. Tổn thương trên da vùng cổ đã hết các sẩn cục, hết ngứa, chỉ còn tổn thương dạng sẹo cũ.&nbsp;</p><p>Bệnh sán dây chó là gì? Con đường lây truyền?&nbsp;</p><p>Theo BSCKI. Lương Thị Nga - Chuyên khoa Nội chung, Phòng khám Đa khoa MEDLATEC Bắc Ninh, bệnh sán dây chó là bệnh gây ra bởi các loài sán thuộc giống&nbsp;Echinococcus. Bệnh sán dây chó ở người có 2 hình thái tổn thương chính:</p><p>Thể nang nước (Cystic echinococcosis-CE).&nbsp;</p><p>Thể nang tổ ong (Alveolar echinococcosis-AE).</p><p>Giống&nbsp;Echinococcus&nbsp;có khoảng 10 loài đã được ghi nhận, trong đó hai loài gây bệnh chính ở người là:&nbsp;E.granulosus&nbsp;và&nbsp;E.multilocularis.&nbsp;</p><p>Về con đường lây nhiễm, bác sĩ Nga cho biết, người mắc bệnh do nuốt phải trứng sán dây chó khi ăn uống các loại thực phẩm, rau sống bị nhiễm bẩn, hoặc tiếp xúc trực tiếp với chó, cáo, chồn nhiễm bệnh mà không rửa tay sạch.&nbsp;</p><p>Khi mắc sán dây chó, người bệnh có những biểu hiện nào?&nbsp;</p><p>Bệnh do ấu trùng sán dây chó&nbsp;Echinococcus&nbsp;có thể lâm sàng phụ thuộc vào loài sán dây chó bị nhiễm. Bệnh tiến triển chậm, có thể không biểu hiện triệu chứng trong thời gian dài. Các nang sán hay ký sinh tại gan (vị trí thường gặp nhất), phổi và các cơ quan khác như thận, lách, tim, tổ chức thần kinh hoặc xương.</p><p>Các nang sán phát triển chậm, ban đầu ít gây triệu chứng, nhưng khi tăng kích thước có thể gây đau, chèn ép cơ quan, rối loạn chức năng gan - phổi, thậm chí đe dọa tính mạng. Đặc biệt, trong trường hợp nang sán vỡ, người bệnh có nguy cơ sốc phản vệ, nhiễm trùng nặng, tăng cao bạch cầu ái toan và IgE, gây biến chứng nguy hiểm. Một số trường hợp bệnh có thể kéo dài nhiều năm, tái phát hoặc phải can thiệp phẫu thuật phức tạp, ảnh hưởng nghiêm trọng đến chất lượng cuộc sống.&nbsp;</p><p>Các phương pháp chẩn đoán sán dây chó&nbsp;</p><p>Với kinh nghiệm thăm khám và điều trị thành công nhiều ca bệnh, bác sĩ Nga chia sẻ các kỹ thuật cần thiết để chẩn đoán sán dây chó, gồm:&nbsp;</p><p><img src=\"https://medlatec.vn/media/42801/file/3-xet-nghiem-mau-don-gian.jpg\"></p><p><br></p><p>Dựa vào các chỉ số xét nghiệm giúp&nbsp;chẩn đoán ban đầu cơ thể có mắc các loại giun sán hay không</p><p><br></p><p>- Xét nghiệm:&nbsp;</p><p><br></p><p>Xét nghiệm huyết thanh học phát hiện kháng thể kháng sán dây chó (kỹ thuật ELISA);&nbsp;</p><p>Công thức máu: bạch cầu ái toan tăng;&nbsp;</p><p>PCR phát hiện gen đặc hiệu của sán dây chó&nbsp;Echinococcus;&nbsp;</p><ul><li>Soi tươi dịch hút từ nang kén thấy hình ảnh đầu sán và móc bám (khi có chỉ định);&nbsp;</li><li>Kỹ thuật khuếch tán miễn dịch hoặc điện di miễn dịch nhằm phát hiện kháng nguyên sán dây chó&nbsp;Echinococcus;&nbsp;</li><li>Xét nghiệm mô bệnh học: hình thái nang đại thể đặc trưng của thể nang nước/nang tổ ong sau khi phẫu thuật.&nbsp;</li></ul><p>- Chẩn đoán hình ảnh:&nbsp;</p><p><br></p><p>Siêu âm: phương pháp cơ bản để chẩn đoán bệnh Echinococcosis, phát hiện nang kén ổ bụng.&nbsp;</p><p>X-quang tim phổi: phát hiện hình ảnh nang kén ở phổi, vùng ngực, xương.</p><p>CT scan, MRI: đánh giá tổn thương ở vị trí khó, đa nang.&nbsp;</p><p>Những cách phòng ngừa ký sinh trùng&nbsp;</p><p>Sán dây chó là bệnh ký sinh trùng có thể phòng tránh được nếu người dân hiểu đúng về con đường lây nhiễm và chủ động thực hiện các biện pháp vệ sinh, an toàn trong sinh hoạt hằng ngày. Thực tế cho thấy, phần lớn các ca bệnh đều có liên quan đến thói quen tiếp xúc gần với chó, ăn rau sống, thực phẩm chưa đảm bảo vệ sinh.</p><p><img src=\"https://medlatec.vn/media/67683/file/cach-phong-giun-san.jpeg\"></p><p><br></p><p>Rửa tay bằng xà phòng sau khi tiếp xúc với vật nuôi là một trong những cách phòng ngừa sán dây chó hiệu quả</p><p><br></p><p>Để phòng bệnh sán dây chó, người dân cần nghiêm túc thực hiện các biện pháp sau:&nbsp;</p><p>Hạn chế tiếp xúc trực tiếp với chó, đặc biệt là chó thả rông; rửa tay sạch bằng xà phòng sau khi tiếp xúc với vật nuôi;&nbsp;</p><p>Không ăn rau sống, thực phẩm chưa được rửa sạch hoặc chưa nấu chín kỹ;&nbsp;</p><p>Đốt hoặc chôn sâu các phủ tạng của vật chủ trung gian bị chết;&nbsp;</p><ul><li>Tẩy sán định kỳ cho chó, quản lý tốt vật nuôi trong gia đình.&nbsp;</li></ul><p>Với mong muốn đồng hành cùng cộng đồng trong việc chủ động bảo vệ sức khỏe, nhân dịp Tết Nguyên đán 2026, từ nay đến hết ngày 31/01/2026, Hệ thống Y tế MEDLATEC triển khai chương trình ưu đãi đặc biệt trên phạm vi toàn quốc dành cho khách hàng sử dụng dịch vụ lấy mẫu xét nghiệm tại nhà.</p><p>Theo đó, mỗi khách hàng được lựa chọn 1 trong 2 ưu đãi:</p><p>Miễn phí xét nghiệm đường máu và mỡ máu&nbsp;(Glucose, Cholesterol, Triglyceride);</p><p>Miễn phí xét nghiệm Toxocara IgG&nbsp;(Giun đũa chó, mèo).</p><p>Chương trình áp dụng với tất cả khách hàng đăng ký sử dụng dịch vụ lấy mẫu xét nghiệm tận nơi trên toàn quốc.</p><p>Chương trình&nbsp;</p><p>không áp dụng</p><p>&nbsp;với khách hàng sử dụng Bảo hiểm y tế, bảo hiểm bảo lãnh; Khách hàng sử dụng kèm các chương trình ưu đãi khác; Khách hàng của Cộng tác viên.</p>','2026-02-04 12:00:27.669850',0,'Sẩn ngứa kéo dài suốt 1 năm, nam sinh đã đi khám và điều trị nhưng không khỏi hẳn. Nam sinh may mắn chấm dứt các tình trạng ngứa ngáy, khó chịu này khi đến khám tại Phòng khám Đa khoa MEDLATEC Bắc Ninh.','http://localhost:8080/api/images/articles/bc023121-a5a2-499d-8788-1366a4a7323f.jpg',_binary '',_binary '\0','2026-02-04 12:00:39.851287','1-nam-san-ngua-nam-sinh-di-kham-phat-hien-nhiem-ky-sinh-trung','Tin tức y khoa','1 năm sẩn ngứa, nam sinh đi khám phát hiện nhiễm ký sinh trùng','2026-02-04 12:00:39.852287','APPROVED',7,'medlatec');
