INSERT INTO `services` VALUES (4,'Đặt lịch','/appointments','#5f79fc','2026-02-03 13:31:15.603717','Quý khách hàng sử dụng tiện ích này để đặt lịch lấy mẫu tại nhà hoặc đặt lịch khám chữa bệnh tại các cơ sở của MEDLATEC',1,NULL,'http://localhost:8080/api/images/articles/ae2b38a7-2be8-4bdc-9c3a-4d23d31de9d2.png',_binary '','Đặt lịch khám, lấy mẫu tại nhà','2026-02-03 13:31:15.603717'),(5,'Xem chi tiết',NULL,'#75c282','2026-02-03 08:50:07.454364','Quý khách hàng sử dụng tiện ích này để tra cứu kết quả sau khi sử dụng dịch vụ y tế tại Hệ thống Y tế MEDLATEC',2,'file-text','http://localhost:8080/api/images/articles/693e2a4b-b8c8-4021-b278-c0e8b0868907.png',_binary '','Tra cứu kết quả','2026-02-03 08:50:07.454364'),(6,'Xem bảng giá',NULL,'#f3a639','2026-02-03 09:15:08.866006','Quý khách hàng sử dụng tiện ích này để tra cứu giá dịch vụ y tế tại Hệ thống Y tế MEDLATEC',3,NULL,'http://localhost:8080/api/images/articles/0f0f3c18-6769-4c40-bbd9-43c101786192.png',_binary '','Bảng giá dịch vụ','2026-02-03 09:15:08.866006'),(7,'Xem chi tiết','/appointment','#eeb417','2026-02-03 13:30:45.143946','Quý khách hàng sử dụng tiện ích này để đặt câu hỏi và nhận hướng dẫn, giải đáp thắc mắc từ chuyên gia y tế của MEDLATEC',4,NULL,'http://localhost:8080/api/images/articles/0a40f906-f2d0-4323-a219-dddb1e82fd97.png',_binary '','Hỏi đáp chuyên gia','2026-02-03 13:30:45.144603');
