INSERT INTO `testimonials` VALUES (1,'2026-02-03 17:35:36.255778','https://images.unsplash.com/photo-1494790108755-2616b612b786?w=100','Chị Nguyễn Thị Lan','Bệnh nhân tim mạch',1,_binary '',_binary '',5,'Mình ấn tượng vì chưa từng khám bệnh ở đâu có sự chuyên nghiệp như MEDLATEC. Trường hợp của mình còn được hội chẩn từ xa với các bác sĩ chuyên gia tại Hà Nội để đưa phác đồ tốt nhất. Cảm ơn MEDLATEC','2026-02-03 17:35:36.255778'),(2,'2026-02-03 17:36:31.322675','https://images.unsplash.com/photo-1472099645785-5658abf4ff4e?w=100','Anh Trần Văn Minh','Khám sức khỏe thần kinh',2,_binary '',_binary '',5,'Chất lượng khám tại Bệnh viện rất tốt, tôi theo dõi bệnh lý mạn tính và khám sức khỏe tổng quát định kỳ thường xuyên. Mọi quy trình đều nhanh gọn, hơn nữa còn rất tiết kiệm chi phí. Tôi đã sử dụng dịch vụ của MEDLATEC hơn 10 năm.','2026-02-03 17:36:31.329721'),(3,'2026-02-03 17:37:10.469849','https://images.unsplash.com/photo-1438761681033-6461ffad8d80?w=100','Chị Phạm Thị Hoa','Khám phụ khoa',3,_binary '',_binary '',5,'Dịch vụ tận nơi thật sự đã giúp tôi và gia đình tiết kiệm thời gian chăm sóc sức khỏe cũng như chi phí, chỉ mất 10.000 đồng chi phí đi lại. Tiện ích đặt lịch nhanh chóng qua app và website, theo dõi sức khỏe online và bảo mật tốt.','2026-02-03 17:37:10.480227');
/*!40000 ALTER TABLE `testimonials` ENABLE KEYS */;
UNLOCK TABLES;

